/**
 * Add a link to this mime type
 *
 * @param link
 */
void addLink(URI link) {
    if (link == null) {
        throw new IllegalArgumentException("Missing Link");
    }
    List<URI> copy = new ArrayList<>(links.size() + 1);
    copy.addAll(links);
    copy.add(link);
    links = Collections.unmodifiableList(copy);
}
